"""Generate BRIEFS_AND_FINALISTS.md (10 tuned-on briefs + 3 held-out briefs; v1.0.0 vs v1.1.0 hooks, review scores and flags)."""
import os, importlib.util
here = os.path.dirname(os.path.abspath(__file__))
def L(p, n):
    s = importlib.util.spec_from_file_location(n, os.path.join(here, p)); m = importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
b1 = L("../baseline/baseline_data.py", "a"); b1h = L("../baseline/baseline_data_heldout.py", "b"); b2 = L("../revised/revised_data.py", "c")
R1 = dict(L("review_v1.py", "d").REVIEW); R1.update(L("review_v1_heldout.py", "e").REVIEW); R2 = L("review_v11.py", "f").REVIEW
old = {b["id"]: b for b in b1.BRIEFS + b1h.BRIEFS}
out = ["<!-- GENERATED by review/make_summary.py -->", "# The 13 briefs and their three finalists (v1.0.0 baseline vs v1.1.0)\n",
       "Rows pair finalists by position only: v1.1 finalists are new candidates, not edits of the v1.0 ones. Scores are 1-5 on clarity / curiosity / originality / Iraqi-naturalness / visual / continuity / scientific accuracy. **The same language model generated and scored everything**, and Iraqi naturalness cannot be judged by it: treat the Iraqi score as a placeholder for the creator's own judgement. B11-B13 are the held-out briefs (baseline frozen before any change; but the reviewer had seen their baseline defects when writing v1.1 - see the report).\n"]
def sc(v): return "/".join(str(x) for x in v[:7])
for b in b2.BRIEFS:
    o = old[b["id"]]
    out.append(f"\n## {b['id']} - {b['title']} ({b['platform']}, {b['dur']} s){' - HELD-OUT' if b['held_out'] else ''}\n")
    out.append(f"*Brief:* {b['brief']}  \n*v1.1 verdict:* {b['verdict']}  \n*v1.1 recommendation:* **{b['rec']}** - {b['why']}\n")
    out.append("| | v1.0.0 hook | scores | flags | v1.1.0 hook | scores | flags |\n|---|---|---|---|---|---|---|")
    for i in range(3):
        f0, f1 = o["fin"][i], b["fin"][i]; k0, k1 = f"{b['id']}-{f0['id']}", f"{b['id']}-{f1['id']}"
        out.append(f"| {f1['id']} | {f0['hook']} | {sc(R1[k0])} | {','.join(R1[k0][7]) or '-'} | {f1['hook']} | {sc(R2[k1])} | {','.join(R2[k1][7]) or '-'} |")
    out.append("\nv1.1 per-finalist spec (gap / first frame / payoff / sources):\n")
    for f in b["fin"]:
        out.append(f"- **{f['id']}** `{f['mech']}` gap: {f['gap']} | frame: {f['frame']} | payoff: {f['payoff']} | sources: {', '.join(sorted({c[1] for c in f['claims'] if c[1]}))}")
    out.append("\nFull retention plans: `baseline/%s.md` (v1.0.0) and `revised/%s.md` (v1.1.0).\n" % (b["id"], b["id"]))
open(os.path.join(here, "..", "BRIEFS_AND_FINALISTS.md"), "w", encoding="utf-8").write("\n".join(out))
print("ok")
